CREATE OR REPLACE FUNCTION public.get_active_delegations_for_user(user_uuid uuid)
 RETURNS TABLE(delegation_id uuid, delegator_id uuid, delegated_role delegatable_role, start_date timestamp with time zone, end_date timestamp with time zone)
 LANGUAGE plpgsql
AS $function$
BEGIN
    -- First, expire any ended delegations
    PERFORM expire_ended_delegations();
    
    RETURN QUERY
    SELECT 
        rd.id as delegation_id,
        rd.delegator_id,
        rd.delegated_role,
        rd.start_date,
        rd.end_date
    FROM role_delegations rd
    WHERE rd.delegate_id = user_uuid
      AND rd.status = 'active'
      AND rd.start_date <= NOW()
      AND (rd.end_date IS NULL OR rd.end_date > NOW());
END;
$function$

CREATE OR REPLACE FUNCTION public.get_approved_permit_polygons()
 RETURNS TABLE(permit_id uuid, permit_number character varying, project_title character varying, coordinates_geojson jsonb, status permit_status, issued_date date, expiry_date date)
 LANGUAGE plpgsql
AS $function$
BEGIN
    RETURN QUERY
    SELECT 
        p.id,
        p.permit_number,
        a.project_title,
        ST_AsGeoJSON(p.coordinates)::JSONB as coordinates_geojson,
        p.status,
        p.issued_date,
        p.expiry_date
    FROM public.permits p
    JOIN public.applications a ON p.application_id = a.id
    WHERE p.coordinates IS NOT NULL
    AND ST_IsValid(p.coordinates)
    ORDER BY p.issued_date DESC;
END;
$function$

CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    existing_user UUID;
BEGIN
    -- Check if user already exists
    SELECT id INTO existing_user FROM public.users WHERE id = NEW.id LIMIT 1;
    
    IF existing_user IS NOT NULL THEN
        RETURN NEW;
    END IF;
    
    -- Insert new user
    BEGIN
        INSERT INTO public.users (
            id, 
            email, 
            role, 
            status, 
            account_type,
            first_name,
            last_name,
            company_name,
            company_tin, 
            company_address,
            company_phone,
            applications_count, 
            reviews_count, 
            inspections_count,
            profile_completed,
            created_at, 
            updated_at
        ) VALUES (
            NEW.id, 
            NEW.email, 
            'applicant', 
            'active', 
            'individual',
            'User',
            'Profile',
            NULL,
            NULL,
            NULL,
            NULL,
            0, 
            0, 
            0,
            FALSE,
            NOW(), 
            NOW()
        );
    EXCEPTION
        WHEN unique_violation THEN
            NULL;
        WHEN OTHERS THEN
            RAISE LOG 'handle_new_user error: %', SQLERRM;
    END;
    
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.has_active_delegation(user_uuid uuid, check_role delegatable_role)
 RETURNS boolean
 LANGUAGE plpgsql
AS $function$
DECLARE
    has_delegation BOOLEAN;
BEGIN
    -- First, expire any ended delegations
    PERFORM expire_ended_delegations();
    
    SELECT EXISTS (
        SELECT 1
        FROM role_delegations rd
        WHERE rd.delegate_id = user_uuid
          AND rd.delegated_role = check_role
          AND rd.status = 'active'
          AND rd.start_date <= NOW()
          AND (rd.end_date IS NULL OR rd.end_date > NOW())
    ) INTO has_delegation;
    
    RETURN has_delegation;
END;
$function$

CREATE OR REPLACE FUNCTION public.increment_quarterly_permits()
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE
    current_year INTEGER;
    current_quarter INTEGER;
    quarter_string VARCHAR(7);
BEGIN
    current_year := EXTRACT(year FROM NOW())::INTEGER;
    current_quarter := EXTRACT(quarter FROM NOW())::INTEGER;
    quarter_string := current_year || '-Q' || current_quarter;
    
    INSERT INTO quarterly_permit_stats (year, quarter_num, quarter, permits_issued)
    VALUES (
        current_year, 
        current_quarter,
        quarter_string,
        1
    )
    ON CONFLICT (year, quarter_num) 
    DO UPDATE SET 
        permits_issued = quarterly_permit_stats.permits_issued + 1,
        updated_at = NOW();
END;
$function$

